INSERT INTO perspective_reports (scope_level, scope_id, scope_label, self_report, expected_behavior, evidence, status) VALUES ('mainjs_function', 'addXP', 'addXP', 'I am a real function defined at main.js legacy block:352, called 22 time(s) elsewhere in rpgace_core.js by a bare same-name call (a real, checkable but NOT exhaustive signal — see this generator''s own honest scope-limit note on hooks/DOM-event/callback-reference calls it cannot see).', 'Real behavior not yet hand-verified against live app use; my role is inferred from my own definition and detected call sites, not confirmed by direct observation.', '[{"cite": "main.js legacy block:352\nfunction addXP(amount){\n  STATE.xp+=amount;STATE.totalXP+=amount;STATE.tasksCompleted++;showXPToast(amount);\n  const req=STATE.xpRequired[STATE.level-1]||9999;\n  paintXpBar(STATE.xp,req);\n  document.getElementById(''xp-val'').textContent=STATE.xp+'' / ''+req;\n  document.getElementById(''stat-tasks'').textContent=STATE.tasksCompleted;\n  document.getElementById(''stat-xp'').textContent=STATE.totalXP;\n  if(STATE.xp>=req)levelUp();", "call_site_count": 22}]'::jsonb, 'unverified');
INSERT INTO perspective_reports (scope_level, scope_id, scope_label, self_report, expected_behavior, evidence, status) VALUES ('mainjs_function', 'agentLog', 'agentLog', 'I am a real function defined at main.js legacy block:285, called 7 time(s) elsewhere in rpgace_core.js by a bare same-name call (a real, checkable but NOT exhaustive signal — see this generator''s own honest scope-limit note on hooks/DOM-event/callback-reference calls it cannot see).', 'Real behavior not yet hand-verified against live app use; my role is inferred from my own definition and detected call sites, not confirmed by direct observation.', '[{"cite": "main.js legacy block:285\nfunction agentLog(msg,type=''info''){\n  const log=document.getElementById(''agent-log''); if(!log) return;\n  const span=document.createElement(''span''); span.className=''log-''+type;\n  span.textContent=''\\n[''+new Date().toLocaleTimeString()+''] ''+msg; log.appendChild(span); log.scrollTop=log.scrollHeight;\n}\n\n// \u2500\u2500 QUESTS \u2500\u2500", "call_site_count": 7}]'::jsonb, 'unverified');
INSERT INTO perspective_reports (scope_level, scope_id, scope_label, self_report, expected_behavior, evidence, status) VALUES ('mainjs_function', 'applyShifts', 'applyShifts', 'I am a real function defined at main.js legacy block:392, called 8 time(s) elsewhere in rpgace_core.js by a bare same-name call (a real, checkable but NOT exhaustive signal — see this generator''s own honest scope-limit note on hooks/DOM-event/callback-reference calls it cannot see).', 'Real behavior not yet hand-verified against live app use; my role is inferred from my own definition and detected call sites, not confirmed by direct observation.', '[{"cite": "main.js legacy block:392\nfunction applyShifts(events,source){STATE.importedShifts=events;events.forEach(ev=>{for(let h=ev.startH;h<ev.endH&&h<24;h++){const inp=document.getElementById(''ti-''+h);if(inp){inp.value=ev.title+(inp.value?'', ''+inp.value:'''');inp.closest(''.time-slot'').classList.add(''shift'',''filled'');}}});const dayMap={mon:0,tue:1,wed:2,thu:3,fri:4,sat:5,sun:6};const wI=document.querySelectorAll(''.day-input'');events.forEach(ev=>{if(ev.dayName){const idx=dayMap[ev.dayName.toLowerCase()];if(idx!==undefined&&wI[idx]){wI[idx].value=(wI[idx].value?wI[idx].value+''\\n'':'''')+`${ev.startH}:00-${ev.endH}:00 ${ev.title}`;}}});const mc=document.querySelectorAll(''.week-col'');if(mc[0]){events.forEach(ev=>{const item=document.createElement(''div'');item.className=''month-task shift-task'';item.innerHTML=`<span>\ud83c\udfe2 ${ev.title} ${ev.startH}:00\u2013${ev.endH}:00</span><span onclick=\"this.parentElement.classList.toggle(''done'')\" style=\"cursor:pointer;font-size:12px\">\u2713</span>`;mc[0].insertBefore(item,mc[0].querySelector(''.add-month-task''));});}const r=document.getElementById(''import-result'');r.style.display=''block'';r.style.borderColor=''var(--green)'';r.style.color=''var(--green)'';r.textContent=`\u2713 Imported ${events.length} shift${events.length!==1?''s'':''''} from ${source}.`;addXP(30);}", "call_site_count": 8}]'::jsonb, 'unverified');
INSERT INTO perspective_reports (scope_level, scope_id, scope_label, self_report, expected_behavior, evidence, status) VALUES ('mainjs_function', 'approveInsights', 'approveInsights', 'I am a real function defined at main.js legacy block:2663, called 3 time(s) elsewhere in rpgace_core.js by a bare same-name call (a real, checkable but NOT exhaustive signal — see this generator''s own honest scope-limit note on hooks/DOM-event/callback-reference calls it cannot see).', 'Real behavior not yet hand-verified against live app use; my role is inferred from my own definition and detected call sites, not confirmed by direct observation.', '[{"cite": "main.js legacy block:2663\nasync function approveInsights(safeId, suggestions, eid, etitle, emacro){\n  let saved=0;\n  for(let i=0;i<suggestions.length;i++){\n    if(!document.getElementById(`ic-${safeId}-${i}`)?.checked) continue;\n    const text = document.getElementById(`it-${safeId}-${i}`)?.value?.trim();\n    if(!text) continue;\n    await sbInsightPost({source_entry_id:eid, source_entry_title:etitle, insight_text:text,\n      micro_categories:suggestions[i].micro_categories||[], macro_category:suggestions[i].macro_category||emacro, status:''approved''});", "call_site_count": 3}]'::jsonb, 'unverified');
INSERT INTO perspective_reports (scope_level, scope_id, scope_label, self_report, expected_behavior, evidence, status) VALUES ('mainjs_function', 'approveInsightsFromCache', 'approveInsightsFromCache', 'I am a real function defined at main.js legacy block:2657, called 1 time(s) elsewhere in rpgace_core.js by a bare same-name call (a real, checkable but NOT exhaustive signal — see this generator''s own honest scope-limit note on hooks/DOM-event/callback-reference calls it cannot see).', 'Real behavior not yet hand-verified against live app use; my role is inferred from my own definition and detected call sites, not confirmed by direct observation.', '[{"cite": "main.js legacy block:2657\nasync function approveInsightsFromCache(safeId){\n  const ctx = window._encSuggestions?.[safeId];\n  if(!ctx){ alert(''Session expired \u2014 re-extract insights.''); return; }\n  await approveInsights(safeId, ctx.suggestions, ctx.eid, ctx.etitle, ctx.emacro);\n}", "call_site_count": 1}]'::jsonb, 'unverified');
INSERT INTO perspective_reports (scope_level, scope_id, scope_label, self_report, expected_behavior, evidence, status) VALUES ('mainjs_function', 'autoApplyStoredShifts', 'autoApplyStoredShifts', 'I am a real function defined at main.js legacy block:1918, called 4 time(s) elsewhere in rpgace_core.js by a bare same-name call (a real, checkable but NOT exhaustive signal — see this generator''s own honest scope-limit note on hooks/DOM-event/callback-reference calls it cannot see).', 'Real behavior not yet hand-verified against live app use; my role is inferred from my own definition and detected call sites, not confirmed by direct observation.', '[{"cite": "main.js legacy block:1918\nfunction autoApplyStoredShifts(){\n  const stored=JSON.parse(localStorage.getItem(''rpgace_shifts'')||''[]'');\n  if(!stored.length)return;\n  const dayNames=[''sun'',''mon'',''tue'',''wed'',''thu'',''fri'',''sat''];\n  const colMap={sun:6,mon:0,tue:1,wed:2,thu:3,fri:4,sat:5};\n  const today=new Date();\n  const dow=today.getDay();\n  const monday=new Date(today);", "call_site_count": 4}]'::jsonb, 'unverified');
INSERT INTO perspective_reports (scope_level, scope_id, scope_label, self_report, expected_behavior, evidence, status) VALUES ('mainjs_function', 'autoExtractAllInCategory', 'autoExtractAllInCategory', 'I am a real function defined at main.js legacy block:2806, called 3 time(s) elsewhere in rpgace_core.js by a bare same-name call (a real, checkable but NOT exhaustive signal — see this generator''s own honest scope-limit note on hooks/DOM-event/callback-reference calls it cannot see).', 'Real behavior not yet hand-verified against live app use; my role is inferred from my own definition and detected call sites, not confirmed by direct observation.', '[{"cite": "main.js legacy block:2806\nasync function autoExtractAllInCategory(macroCategory){\n  const entries=macroCategory===''all''?ENC_ALL_ENTRIES:ENC_ALL_ENTRIES.filter(e=>detectCategory(e.content,e.title)===macroCategory);\n  if(!entries.length){alert(''No entries in this category yet.'');return;}\n  const btn=event?.target;\n  if(btn){btn.disabled=true;btn.textContent=`Extracting from ${entries.length} entries...`;}\n  for(const entry of entries) await extractInsightsAuto(entry,true);\n  if(btn){btn.disabled=false;btn.textContent=''\u26a1 Auto-extract more'';}\n  await loadInsightsByCategory(macroCategory);", "call_site_count": 3}]'::jsonb, 'unverified');
INSERT INTO perspective_reports (scope_level, scope_id, scope_label, self_report, expected_behavior, evidence, status) VALUES ('mainjs_function', 'buildAgentActions', 'buildAgentActions', 'I am a real function defined at main.js legacy block:240, called 4 time(s) elsewhere in rpgace_core.js by a bare same-name call (a real, checkable but NOT exhaustive signal — see this generator''s own honest scope-limit note on hooks/DOM-event/callback-reference calls it cannot see).', 'Real behavior not yet hand-verified against live app use; my role is inferred from my own definition and detected call sites, not confirmed by direct observation.', '[{"cite": "main.js legacy block:240\nfunction buildAgentActions(){\n  const el=document.getElementById(''agent-actions''); if(!el) return; el.innerHTML='''';\n  AGENT_ACTIONS.forEach(a=>{\n    const d=document.createElement(''div''); d.className=''quest-card career'';\n    d.innerHTML=`<div class=\"quest-top\"><div class=\"quest-name\">${a.icon} ${a.name}</div><div class=\"quest-xp\">+${a.xp} XP</div></div><div class=\"quest-desc\">${a.desc}</div><div class=\"quest-tags\"><span class=\"tag career\">${a.app}</span><span class=\"tag daily\">agent</span></div><button class=\"complete-btn\" onclick=\"triggerAgent(''${a.id}'')\">\u26a1 Execute</button>`;\n    el.appendChild(d);\n  });\n}", "call_site_count": 4}]'::jsonb, 'unverified');
INSERT INTO perspective_reports (scope_level, scope_id, scope_label, self_report, expected_behavior, evidence, status) VALUES ('mainjs_function', 'buildAllQuests', 'buildAllQuests', 'I am a real function defined at main.js legacy block:304, called 5 time(s) elsewhere in rpgace_core.js by a bare same-name call (a real, checkable but NOT exhaustive signal — see this generator''s own honest scope-limit note on hooks/DOM-event/callback-reference calls it cannot see).', 'Real behavior not yet hand-verified against live app use; my role is inferred from my own definition and detected call sites, not confirmed by direct observation.', '[{"cite": "main.js legacy block:304\nfunction buildAllQuests(){buildQS(''daily-quests'',QUESTS.daily);buildQS(''weekly-quests'',QUESTS.weekly);buildQS(''career-quests'',QUESTS.career);buildQS(''health-quests'',QUESTS.health);buildQS(''lifestyle-quests'',QUESTS.lifestyle);}\n// A9 Phase 1 (Aug 23 2026): two real changes.\n// 1. The group list was hardcoded to the 5 original QUESTS keys, so any\n//    future group would have been silently uncompletable. It now walks\n//    whatever groups QUESTS actually has.\n// 2. This used to be the whole story - a done-flag on an in-memory\n//    object and an addXP() that mutated an in-memory STATE, with zero\n//    persistence anywhere, so every completion evaporated on the next", "call_site_count": 5}]'::jsonb, 'unverified');
INSERT INTO perspective_reports (scope_level, scope_id, scope_label, self_report, expected_behavior, evidence, status) VALUES ('mainjs_function', 'buildMonthSlots', 'buildMonthSlots', 'I am a real function defined at main.js legacy block:1967, called 4 time(s) elsewhere in rpgace_core.js by a bare same-name call (a real, checkable but NOT exhaustive signal — see this generator''s own honest scope-limit note on hooks/DOM-event/callback-reference calls it cannot see).', 'Real behavior not yet hand-verified against live app use; my role is inferred from my own definition and detected call sites, not confirmed by direct observation.', '[{"cite": "main.js legacy block:1967\nfunction buildMonthSlots(){\n  const el=document.getElementById(''month-slots'');if(!el)return;el.innerHTML='''';\n  const ref=window._calMonthDate,yr=ref.getFullYear(),mo=ref.getMonth();\n  const btnS=''background:rgba(255,255,255,0.06);border:1px solid rgba(255,255,255,0.1);color:#E2E2EC;padding:5px 13px;border-radius:5px;cursor:pointer;font-family:Rajdhani,sans-serif;font-size:12px;font-weight:700;'';\n  const moName=ref.toLocaleDateString(''en-GB'',{month:''long'',year:''numeric''});\n  const nav=document.createElement(''div'');nav.style.cssText=''display:flex;align-items:center;justify-content:space-between;margin-bottom:14px;'';\n  nav.innerHTML=''<button onclick=\"calMonthNav(-1)\" style=\"''+btnS+''\">\\u25C4</button>''\n    +''<div style=\"text-align:center\"><div style=\"font-family:Cinzel,serif;font-size:14px;color:#C9A84C\">''+moName+''</div>''", "call_site_count": 4}]'::jsonb, 'unverified');
