INSERT INTO perspective_reports (scope_level, scope_id, scope_label, self_report, expected_behavior, evidence, status) VALUES ('mainjs_function', 'buildSkillTree', 'buildSkillTree', 'I am a real function defined at main.js legacy block:935, called 3 time(s) elsewhere in rpgace_core.js by a bare same-name call (a real, checkable but NOT exhaustive signal — see this generator''s own honest scope-limit note on hooks/DOM-event/callback-reference calls it cannot see).', 'Real behavior not yet hand-verified against live app use; my role is inferred from my own definition and detected call sites, not confirmed by direct observation.', '[{"cite": "main.js legacy block:935\nfunction buildSkillTree(){const el=document.getElementById(''skill-tree'');if(!el)return;el.innerHTML='''';SKILLS.forEach(s=>{const n=document.createElement(''div'');n.className=''skill-node''+(s.active?'' active'':'''');n.innerHTML=`<span class=\"skill-icon\">${s.icon}</span><div class=\"skill-name\">${s.name}</div><div class=\"skill-desc\">${s.desc}</div><div class=\"skill-req\">${s.active?''\u2713 Unlocked'':s.req}</div>`;el.appendChild(n);});}", "call_site_count": 3}]'::jsonb, 'unverified');
