INSERT INTO perspective_reports (scope_level, scope_id, scope_label, self_report, expected_behavior, evidence, status) VALUES ('mainjs_function', 'buildWeekSlots', 'buildWeekSlots', 'I am a real function defined at main.js legacy block:2004, called 3 time(s) elsewhere in rpgace_core.js by a bare same-name call (a real, checkable but NOT exhaustive signal — see this generator''s own honest scope-limit note on hooks/DOM-event/callback-reference calls it cannot see).', 'Real behavior not yet hand-verified against live app use; my role is inferred from my own definition and detected call sites, not confirmed by direct observation.', '[{"cite": "main.js legacy block:2004\nfunction buildWeekSlots(){\n  const el=document.getElementById(''week-slots'');if(!el)return;el.innerHTML='''';\n  if(!window._calWeekStart)window._calWeekStart=_calMondayOf(new Date());\n  const monday=new Date(window._calWeekStart),endSun=new Date(monday);endSun.setDate(monday.getDate()+6);\n  const wNum=Math.ceil(monday.getDate()/7);\n  const wLabel=''Week ''+wNum+'' \\u00B7 ''+monday.toLocaleDateString(''en-GB'',{day:''numeric'',month:''short''})+''\\u2013''+endSun.toLocaleDateString(''en-GB'',{day:''numeric'',month:''short'',year:''numeric''});\n  const btnS=''background:rgba(255,255,255,0.06);border:1px solid rgba(255,255,255,0.1);color:#E2E2EC;padding:5px 13px;border-radius:5px;cursor:pointer;font-family:Rajdhani,sans-serif;font-size:12px;font-weight:700;'';\n  const nav=document.createElement(''div'');nav.style.cssText=''display:flex;align-items:center;justify-content:space-between;margin-bottom:14px;'';", "call_site_count": 3}]'::jsonb, 'unverified');
