INSERT INTO perspective_reports (scope_level, scope_id, scope_label, self_report, expected_behavior, evidence, status) VALUES ('mainjs_function', 'collapseEncEntry', 'collapseEncEntry', 'I am a real function defined at main.js legacy block:3433, called 3 time(s) elsewhere in rpgace_core.js by a bare same-name call (a real, checkable but NOT exhaustive signal — see this generator''s own honest scope-limit note on hooks/DOM-event/callback-reference calls it cannot see).', 'Real behavior not yet hand-verified against live app use; my role is inferred from my own definition and detected call sites, not confirmed by direct observation.', '[{"cite": "main.js legacy block:3433\nfunction collapseEncEntry(safeId){\n  const collapsed = document.getElementById(''enc-collapsed-'' + safeId);\n  const expanded  = document.getElementById(''enc-expanded-''  + safeId);\n  const chevron   = document.getElementById(''enc-chevron-''   + safeId);\n  if(collapsed) collapsed.style.display = ''block'';\n  if(expanded)  expanded.style.display  = ''none'';\n  if(chevron)   chevron.textContent      = ''\u25bc'';\n}", "call_site_count": 3}]'::jsonb, 'unverified');
INSERT INTO perspective_reports (scope_level, scope_id, scope_label, self_report, expected_behavior, evidence, status) VALUES ('mainjs_function', 'compileEncyclopedia', 'compileEncyclopedia', 'I am a real function defined at main.js legacy block:4605, called 1 time(s) elsewhere in rpgace_core.js by a bare same-name call (a real, checkable but NOT exhaustive signal — see this generator''s own honest scope-limit note on hooks/DOM-event/callback-reference calls it cannot see).', 'Real behavior not yet hand-verified against live app use; my role is inferred from my own definition and detected call sites, not confirmed by direct observation.', '[{"cite": "main.js legacy block:4605\nasync function compileEncyclopedia(){\n  if(!LEARN.db.length){ alert(''Save at least one set of notes first.''); return; }\n  setLearnStatus(''enc-status'',''Compiling encyclopedia...'',''loading'');\n  document.getElementById(''enc-output'').innerHTML = ''<div style=\"color:var(--muted);padding:16px\">AI is reading all your notes and organising them into an encyclopedia...</div>'';\n\n  const allNotes = LEARN.db.map((n,i)=>`--- NOTE ${i+1}: \"${n.videoTitle}\" (${n.topic}) ---\\n${n.notes}`).join(''\\n\\n'');\n  const topics = [...new Set(LEARN.db.map(n=>n.topic))];\n", "call_site_count": 1}]'::jsonb, 'unverified');
INSERT INTO perspective_reports (scope_level, scope_id, scope_label, self_report, expected_behavior, evidence, status) VALUES ('mainjs_function', 'completeQuest', 'completeQuest', 'I am a real function defined at main.js legacy block:319, called 9 time(s) elsewhere in rpgace_core.js by a bare same-name call (a real, checkable but NOT exhaustive signal — see this generator''s own honest scope-limit note on hooks/DOM-event/callback-reference calls it cannot see).', 'Real behavior not yet hand-verified against live app use; my role is inferred from my own definition and detected call sites, not confirmed by direct observation.', '[{"cite": "main.js legacy block:319\nfunction completeQuest(id,xp,btn){\n  const all=Object.keys(QUESTS).reduce((acc,k)=>acc.concat(QUESTS[k]||[]),[]);\n  const q=all.find(x=>x.id===id);if(!q||q.done)return;\n  q.done=true;btn.textContent=''\u2713 Completed'';btn.classList.add(''done'');btn.closest(''.quest-card'').classList.add(''done'');addXP(xp);\n  try{\n    const qe=window.RPGACE&&RPGACE.modules&&RPGACE.modules.questEngine;\n    if(qe&&qe.recordBoardCompletion)qe.recordBoardCompletion(q);\n  }catch(e){console.warn(''[completeQuest] persistence:'',e.message);}", "call_site_count": 9}]'::jsonb, 'unverified');
INSERT INTO perspective_reports (scope_level, scope_id, scope_label, self_report, expected_behavior, evidence, status) VALUES ('mainjs_function', 'completeScheduledTask', 'completeScheduledTask', 'I am a real function defined at main.js legacy block:2301, called 2 time(s) elsewhere in rpgace_core.js by a bare same-name call (a real, checkable but NOT exhaustive signal — see this generator''s own honest scope-limit note on hooks/DOM-event/callback-reference calls it cannot see).', 'Real behavior not yet hand-verified against live app use; my role is inferred from my own definition and detected call sites, not confirmed by direct observation.', '[{"cite": "main.js legacy block:2301\nfunction completeScheduledTask(id){\n  const stored=JSON.parse(localStorage.getItem(''rpgace_sched_agendas'')||''[]'');\n  const idx=stored.findIndex(function(a){return a.id===id;});\n  if(idx<0)return null;\n  const entry=stored[idx],endedAt=new Date();\n  entry.ended_at=endedAt.toISOString();entry.completed=true;\n  if(entry.started_at){const startedAt=new Date(entry.started_at);entry.actual_mins=Math.round((endedAt-startedAt)/60000);}\n  stored[idx]=entry;localStorage.setItem(''rpgace_sched_agendas'',JSON.stringify(stored));", "call_site_count": 2}]'::jsonb, 'unverified');
INSERT INTO perspective_reports (scope_level, scope_id, scope_label, self_report, expected_behavior, evidence, status) VALUES ('mainjs_function', 'confirmSchedule', 'confirmSchedule', 'I am a real function defined at main.js legacy block:1046, called 1 time(s) elsewhere in rpgace_core.js by a bare same-name call (a real, checkable but NOT exhaustive signal — see this generator''s own honest scope-limit note on hooks/DOM-event/callback-reference calls it cannot see).', 'Real behavior not yet hand-verified against live app use; my role is inferred from my own definition and detected call sites, not confirmed by direct observation.', '[{"cite": "main.js legacy block:1046\nfunction confirmSchedule(idx){\n  const a=AGENDA_LIST[idx];if(!a)return;\n  const timeEl=document.getElementById(`sched-time-${idx}`);\n  const time=timeEl?timeEl.value:''19:00'';\n  const parts=(time||''19:00'').split('':'');\n  const hour=parseInt(parts[0])||19, minute=parseInt(parts[1])||0;\n  const dateStr=(typeof _calDateStr===''function''?_calDateStr(new Date()):new Date().toISOString().split(''T'')[0]);\n  scheduleToCalendar({title:a.title,category:a.category,duration_mins:a.duration_mins,hour,minute,date:dateStr,xp:a.xp,source_type:''agenda''});", "call_site_count": 1}]'::jsonb, 'unverified');
