INSERT INTO perspective_reports (scope_level, scope_id, scope_label, self_report, expected_behavior, evidence, status) VALUES ('mainjs_function', 'deleteEncEntry', 'deleteEncEntry', 'I am a real function defined at main.js legacy block:3442, called 2 time(s) elsewhere in rpgace_core.js by a bare same-name call (a real, checkable but NOT exhaustive signal — see this generator''s own honest scope-limit note on hooks/DOM-event/callback-reference calls it cannot see).', 'Real behavior not yet hand-verified against live app use; my role is inferred from my own definition and detected call sites, not confirmed by direct observation.', '[{"cite": "main.js legacy block:3442\nasync function deleteEncEntry(id){\n  if(!confirm(''Delete this encyclopedia entry?'')) return;\n  if(id && String(id).includes(''-'') && String(id).length > 20){\n    try {\n      await RPGACE.sb.secureWrite(''encyclopedia'', ''delete'', null, ''id=eq.'' + id);\n    } catch(e){}\n  }\n  // Aug 27 2026 (/Routine item #1) \u2014 only entries with a real source_url", "call_site_count": 2}]'::jsonb, 'unverified');
