INSERT INTO perspective_reports (scope_level, scope_id, scope_label, self_report, expected_behavior, evidence, status) VALUES ('mainjs_function', 'extractInsightsAuto', 'extractInsightsAuto', 'I am a real function defined at main.js legacy block:2593, called 3 time(s) elsewhere in rpgace_core.js by a bare same-name call (a real, checkable but NOT exhaustive signal — see this generator''s own honest scope-limit note on hooks/DOM-event/callback-reference calls it cannot see).', 'Real behavior not yet hand-verified against live app use; my role is inferred from my own definition and detected call sites, not confirmed by direct observation.', '[{"cite": "main.js legacy block:2593\nasync function extractInsightsAuto(entry, silent=true){\n  const eid = String(entry.id||entry.created_at||entry.title||'''');\n  if(ENC_INSIGHT_CACHE[eid]) return ENC_INSIGHT_CACHE[eid];\n  const prompt = `Extract 5-10 specific standalone insights from this music producer encyclopedia entry.\nEach insight = one concrete fact, technique or observation under 25 words.\nGood examples: \"EQ cut at 300hz in melody bus removes muddiness from stacked pads\" | \"J Cole''s beats use 3-note descending melodies over sparse 808 patterns\"\n\nEntry: ${entry.title}", "call_site_count": 3}]'::jsonb, 'unverified');
