INSERT INTO perspective_reports (scope_level, scope_id, scope_label, self_report, expected_behavior, evidence, status) VALUES ('mainjs_function', 'extractTopic', 'extractTopic', 'I am a real function defined at main.js legacy block:4522, called 1 time(s) elsewhere in rpgace_core.js by a bare same-name call (a real, checkable but NOT exhaustive signal — see this generator''s own honest scope-limit note on hooks/DOM-event/callback-reference calls it cannot see).', 'Real behavior not yet hand-verified against live app use; my role is inferred from my own definition and detected call sites, not confirmed by direct observation.', '[{"cite": "main.js legacy block:4522\nfunction extractTopic(title){\n  const topics = [''mixing'',''mastering'',''production'',''marketing'',''branding'',''youtube'',''tiktok'',''instagram'',''songwriting'',''beats'',''sampling'',''plugins'',''workflow'',''mindset'',''business'',''social media'',''content'',''editing'',''thumbnail'',''SEO''];\n  const t = title.toLowerCase();\n  return topics.find(tp=>t.includes(tp)) || ''general'';\n}", "call_site_count": 1}]'::jsonb, 'unverified');
INSERT INTO perspective_reports (scope_level, scope_id, scope_label, self_report, expected_behavior, evidence, status) VALUES ('mainjs_function', 'extractVSTContext', 'extractVSTContext', 'I am a real function defined at main.js legacy block:2961, called 2 time(s) elsewhere in rpgace_core.js by a bare same-name call (a real, checkable but NOT exhaustive signal — see this generator''s own honest scope-limit note on hooks/DOM-event/callback-reference calls it cannot see).', 'Real behavior not yet hand-verified against live app use; my role is inferred from my own definition and detected call sites, not confirmed by direct observation.', '[{"cite": "main.js legacy block:2961\nfunction extractVSTContext(content, vstName){\n  if(!content||!vstName) return '''';\n  const sentences=content.split(/[.!?\\n]+/).map(s=>s.trim()).filter(s=>s.length>0);\n  const re=new RegExp(vstName.replace(/[.*+?^${}()|[\\]\\\\]/g,''\\\\$&''),''i'');\n  const found=sentences.find(s=>re.test(s));\n  if(!found) return '''';\n  return found.length>80?found.slice(0,80)+''...'':found;\n}", "call_site_count": 2}]'::jsonb, 'unverified');
INSERT INTO perspective_reports (scope_level, scope_id, scope_label, self_report, expected_behavior, evidence, status) VALUES ('mainjs_function', 'extractVSTsFromText', 'extractVSTsFromText', 'I am a real function defined at main.js legacy block:2909, called 6 time(s) elsewhere in rpgace_core.js by a bare same-name call (a real, checkable but NOT exhaustive signal — see this generator''s own honest scope-limit note on hooks/DOM-event/callback-reference calls it cannot see).', 'Real behavior not yet hand-verified against live app use; my role is inferred from my own definition and detected call sites, not confirmed by direct observation.', '[{"cite": "main.js legacy block:2909\nfunction extractVSTsFromText(text){\n  if(!text) return [];\n  const found = new Set();\n  const matches = text.match(VST_PATTERN) || [];\n  matches.forEach(m => found.add(\n    VST_KNOWN.find(v => v.toLowerCase() === m.toLowerCase()) || m\n  ));\n  // Also catch patterns like \"[Name] preset\", \"[Name] kit\", \"[Name] pack\"", "call_site_count": 6}]'::jsonb, 'unverified');
