INSERT INTO perspective_reports (scope_level, scope_id, scope_label, self_report, expected_behavior, evidence, status) VALUES ('mainjs_function', 'filterEntries', 'filterEntries', 'I am a real function defined at main.js legacy block:3236, called 2 time(s) elsewhere in rpgace_core.js by a bare same-name call (a real, checkable but NOT exhaustive signal — see this generator''s own honest scope-limit note on hooks/DOM-event/callback-reference calls it cannot see).', 'Real behavior not yet hand-verified against live app use; my role is inferred from my own definition and detected call sites, not confirmed by direct observation.', '[{"cite": "main.js legacy block:3236\nfunction filterEntries(entries){\n  if(ENC_CATEGORY === ''all'') return entries;\n  return entries.filter(e => detectCategory(e.content, e.title) === ENC_CATEGORY);\n}\n\n// Aug 6 (Alex''s real /deduplication ask, surfaced by the Fallback Scout\n// list showing the SAME encyclopedia entries re-queued repeatedly):\n// ENC_BULLET_CACHE alone is NOT real dedup - it''s a plain in-memory JS", "call_site_count": 2}]'::jsonb, 'unverified');
INSERT INTO perspective_reports (scope_level, scope_id, scope_label, self_report, expected_behavior, evidence, status) VALUES ('mainjs_function', 'generateContentIdeasFromInsights', 'generateContentIdeasFromInsights', 'I am a real function defined at main.js legacy block:2793, called 2 time(s) elsewhere in rpgace_core.js by a bare same-name call (a real, checkable but NOT exhaustive signal — see this generator''s own honest scope-limit note on hooks/DOM-event/callback-reference calls it cannot see).', 'Real behavior not yet hand-verified against live app use; my role is inferred from my own definition and detected call sites, not confirmed by direct observation.', '[{"cite": "main.js legacy block:2793\nasync function generateContentIdeasFromInsights(){\n  const insights=await sbInsightFetch(null);\n  if(!insights.length){alert(''No insights yet \u2014 extract some first.'');return;}\n  const texts=insights.slice(0,25).map(i=>`\u2022 ${i.insight_text}`).join(''\\n'');\n  const input=document.getElementById(''chat-input'');\n  if(input) input.value=`Run command 3 \u2014 Here are specific insights from my music production encyclopedia. Turn the most content-worthy ones into a week of Instagram posts for @AceSanyaBeats:\\n\\n${texts}`;\n  window._instaOracleActive=true;\n  const tab=document.querySelector(''[onclick*=\"advisor\"]'');", "call_site_count": 2}]'::jsonb, 'unverified');
