INSERT INTO perspective_reports (scope_level, scope_id, scope_label, self_report, expected_behavior, evidence, status) VALUES ('mainjs_function', 'handleFocusSelect', 'handleFocusSelect', 'I am a real function defined at main.js legacy block:1259, called 1 time(s) elsewhere in rpgace_core.js by a bare same-name call (a real, checkable but NOT exhaustive signal — see this generator''s own honest scope-limit note on hooks/DOM-event/callback-reference calls it cannot see).', 'Real behavior not yet hand-verified against live app use; my role is inferred from my own definition and detected call sites, not confirmed by direct observation.', '[{"cite": "main.js legacy block:1259\nasync function handleFocusSelect(){\n  const sel = window.getSelection();\n  if(!sel || sel.isCollapsed || sel.toString().trim().length < 5) return;\n  const selectedText = sel.toString().trim();\n  const node = sel.anchorNode?.parentElement;\n  const container = node?.closest(''.focus-selectable'');\n  const fullText = container ? container.textContent : '''';\n  const selIdx = fullText.indexOf(selectedText);", "call_site_count": 1}]'::jsonb, 'unverified');
