INSERT INTO perspective_reports (scope_level, scope_id, scope_label, self_report, expected_behavior, evidence, status) VALUES ('mainjs_function', 'initApp', 'initApp', 'I am a real function defined at main.js legacy block:2335, called 8 time(s) elsewhere in rpgace_core.js by a bare same-name call (a real, checkable but NOT exhaustive signal — see this generator''s own honest scope-limit note on hooks/DOM-event/callback-reference calls it cannot see).', 'Real behavior not yet hand-verified against live app use; my role is inferred from my own definition and detected call sites, not confirmed by direct observation.', '[{"cite": "main.js legacy block:2335\nfunction initApp(){\n  buildAllQuests();buildTimeSlots();buildWeekSlots();buildMonthSlots();buildSkillTree();buildAgentActions();initLearning();\n  addMsg(`Greetings, Creator. I am the Oracle \u2014 now fully wired to your apps.\\n\\nI can talk AND act in the same message:\\n\ud83d\udce7 \"Draft a collab email\" \u2192 fires Gmail instantly\\n\ud83d\udcd3 \"Log today''s progress\" \u2192 creates a Notion page\\n\ud83c\udfac \"Check my YouTube stats\" \u2192 fetches live data\\n\ud83d\udcbb \"Save these notes to GitHub\" \u2192 commits a file\\n\\nJust talk to me naturally. I''ll handle the rest.\\n\\nWhat do you need today?`,''ai'');\n  setTimeout(()=>{\n    // Guarded - #popup-msg no longer exists in current DOM (stale first-time\n    // onboarding element, was throwing on every page load per user report).\n    var pm=document.getElementById(''popup-msg''); if(pm) pm.textContent=''Welcome to RPGACE. Ready to earn your first XP?'';\n    var pt=document.getElementById(''popup-tasks''); if(pt) pt.innerHTML=''<div class=\"popup-task\"><span>\u2694 Post your first TikTok video</span><span class=\"popup-task-xp\">+80 XP</span></div>'';", "call_site_count": 8}]'::jsonb, 'unverified');
