INSERT INTO perspective_reports (scope_level, scope_id, scope_label, self_report, expected_behavior, evidence, status) VALUES ('mainjs_function', 'mergeByUrl', 'mergeByUrl', 'I am a real function defined at main.js legacy block:4336, called 5 time(s) elsewhere in rpgace_core.js by a bare same-name call (a real, checkable but NOT exhaustive signal — see this generator''s own honest scope-limit note on hooks/DOM-event/callback-reference calls it cannot see).', 'Real behavior not yet hand-verified against live app use; my role is inferred from my own definition and detected call sites, not confirmed by direct observation.', '[{"cite": "main.js legacy block:4336\nfunction mergeByUrl(primary,secondary){\n  const seen=new Set(primary.map(r=>r.url));\n  const merged=[...primary];\n  for(const r of secondary) if(!seen.has(r.url)){merged.push(r);seen.add(r.url);}\n  return merged.sort((a,b)=>new Date(b.date||b.created_at||0)-new Date(a.date||a.created_at||0));\n}", "call_site_count": 5}]'::jsonb, 'unverified');
