INSERT INTO perspective_reports (scope_level, scope_id, scope_label, self_report, expected_behavior, evidence, status) VALUES ('mainjs_function', 'parseAndSaveRota', 'parseAndSaveRota', 'I am a real function defined at main.js legacy block:1500, called 2 time(s) elsewhere in rpgace_core.js by a bare same-name call (a real, checkable but NOT exhaustive signal — see this generator''s own honest scope-limit note on hooks/DOM-event/callback-reference calls it cannot see).', 'Real behavior not yet hand-verified against live app use; my role is inferred from my own definition and detected call sites, not confirmed by direct observation.', '[{"cite": "main.js legacy block:1500\nfunction parseAndSaveRota(){\n  const input = document.getElementById(''rota-paste-input'');\n  if(!input) return;\n  const text = input.value.trim();\n  if(!text){ alert(''Please paste your shifts first''); return; }\n  const lines = text.split(''\\n'').map(l=>l.trim()).filter(l=>l);\n  const shifts = [];\n  const dayNames = [''SUN'',''MON'',''TUE'',''WED'',''THU'',''FRI'',''SAT''];", "call_site_count": 2}]'::jsonb, 'unverified');
INSERT INTO perspective_reports (scope_level, scope_id, scope_label, self_report, expected_behavior, evidence, status) VALUES ('mainjs_function', 'parseCSV', 'parseCSV', 'I am a real function defined at main.js legacy block:390, called 2 time(s) elsewhere in rpgace_core.js by a bare same-name call (a real, checkable but NOT exhaustive signal — see this generator''s own honest scope-limit note on hooks/DOM-event/callback-reference calls it cannot see).', 'Real behavior not yet hand-verified against live app use; my role is inferred from my own definition and detected call sites, not confirmed by direct observation.', '[{"cite": "main.js legacy block:390\nfunction parseCSV(text){const lines=text.split(''\\n'').filter(l=>l.trim());const events=[];lines.slice(1).forEach(line=>{const cols=line.split('','').map(c=>c.replace(/\"/g,'''').trim());if(cols.length>=2){const tm=(cols[1]||'''').match(/(\\d+):(\\d+)\\s*[-\u2013to]+\\s*(\\d+):(\\d+)/);events.push({title:cols[0]||''Shift'',startH:tm?parseInt(tm[1]):9,endH:tm?parseInt(tm[3]):17});}});if(events.length)applyShifts(events,''CSV'');else parseText(text);}", "call_site_count": 2}]'::jsonb, 'unverified');
INSERT INTO perspective_reports (scope_level, scope_id, scope_label, self_report, expected_behavior, evidence, status) VALUES ('mainjs_function', 'parseICS', 'parseICS', 'I am a real function defined at main.js legacy block:389, called 2 time(s) elsewhere in rpgace_core.js by a bare same-name call (a real, checkable but NOT exhaustive signal — see this generator''s own honest scope-limit note on hooks/DOM-event/callback-reference calls it cannot see).', 'Real behavior not yet hand-verified against live app use; my role is inferred from my own definition and detected call sites, not confirmed by direct observation.', '[{"cite": "main.js legacy block:389\nfunction parseICS(text){const events=[];text.split(''BEGIN:VEVENT'').slice(1).forEach(block=>{const s=(block.match(/SUMMARY:(.+)/)||['''',''Shift''])[1].trim();const ds=(block.match(/DTSTART[^:]*:(\\d+T\\d+)/)||['''',''''])[1];const de=(block.match(/DTEND[^:]*:(\\d+T\\d+)/)||['''',''''])[1];if(ds){const sH=parseInt(ds.substring(9,11)),eH=de?parseInt(de.substring(9,11)):sH+8;events.push({title:s,startH:sH,endH:eH});}});if(events.length)applyShifts(events,''ICS'');else showImportErr(''No events found in ICS file.'');}", "call_site_count": 2}]'::jsonb, 'unverified');
INSERT INTO perspective_reports (scope_level, scope_id, scope_label, self_report, expected_behavior, evidence, status) VALUES ('mainjs_function', 'parseInsightJSON', 'parseInsightJSON', 'I am a real function defined at main.js legacy block:2574, called 3 time(s) elsewhere in rpgace_core.js by a bare same-name call (a real, checkable but NOT exhaustive signal — see this generator''s own honest scope-limit note on hooks/DOM-event/callback-reference calls it cannot see).', 'Real behavior not yet hand-verified against live app use; my role is inferred from my own definition and detected call sites, not confirmed by direct observation.', '[{"cite": "main.js legacy block:2574\nfunction parseInsightJSON(raw){\n  if(!raw) return [];\n  const cleaned = raw.replace(/```json|```/g,'''').trim();\n  try{ const r=JSON.parse(cleaned); if(Array.isArray(r)) return r.filter(i=>i&&i.insight); }catch(e){}\n  try{ const m=cleaned.match(/\\[[\\s\\S]*\\]/); if(m){ const r=JSON.parse(m[0]); if(Array.isArray(r)) return r.filter(i=>i&&i.insight); } }catch(e){}\n  try{\n    const objs=[]; const re=/\\{[^{}]*\"insight\"\\s*:[^{}]*\\}/g; let match;\n    while((match=re.exec(cleaned))!==null){ try{ const o=JSON.parse(match[0]); if(o.insight) objs.push(o); }catch(e){} }", "call_site_count": 3}]'::jsonb, 'unverified');
INSERT INTO perspective_reports (scope_level, scope_id, scope_label, self_report, expected_behavior, evidence, status) VALUES ('mainjs_function', 'parseText', 'parseText', 'I am a real function defined at main.js legacy block:391, called 3 time(s) elsewhere in rpgace_core.js by a bare same-name call (a real, checkable but NOT exhaustive signal — see this generator''s own honest scope-limit note on hooks/DOM-event/callback-reference calls it cannot see).', 'Real behavior not yet hand-verified against live app use; my role is inferred from my own definition and detected call sites, not confirmed by direct observation.', '[{"cite": "main.js legacy block:391\nfunction parseText(text){const lines=text.split(''\\n'').filter(l=>l.trim());const events=[];const timeRx=/(\\d{1,2}):(\\d{2})\\s*(?:to|-|\u2013)\\s*(\\d{1,2}):(\\d{2})/;const dayRx=/(mon|tue|wed|thu|fri|sat|sun)/i;lines.forEach(line=>{const tm=line.match(timeRx),dm=line.match(dayRx);if(tm||dm){const sH=tm?parseInt(tm[1]):9,eH=tm?parseInt(tm[3]):17,day=dm?dm[1][0].toUpperCase()+dm[1].slice(1).toLowerCase():'''';const parts=line.split(/[-\u2013|]/);events.push({title:parts[parts.length-1].trim()||''Work Shift'',startH:sH,endH:eH,dayName:day});}});if(events.length)applyShifts(events,''text'');else showImportErr(''Could not parse. Try .ics or .csv format.'');}", "call_site_count": 3}]'::jsonb, 'unverified');
