INSERT INTO perspective_reports (scope_level, scope_id, scope_label, self_report, expected_behavior, evidence, status) VALUES ('mainjs_function', 'renderInstaMsg', 'renderInstaMsg', 'I am a real function defined at main.js legacy block:505, called 2 time(s) elsewhere in rpgace_core.js by a bare same-name call (a real, checkable but NOT exhaustive signal — see this generator''s own honest scope-limit note on hooks/DOM-event/callback-reference calls it cannot see).', 'Real behavior not yet hand-verified against live app use; my role is inferred from my own definition and detected call sites, not confirmed by direct observation.', '[{"cite": "main.js legacy block:505\nfunction renderInstaMsg(text){\n  // Render hashtags as chips, captions as copyable boxes, quests as buttons\n  let html = renderMarkdown(text);\n  // Wrap hashtag sets in chip format\n  html = html.replace(/(#\\w+)/g, ''<span onclick=\"navigator.clipboard.writeText(\\''$1\\'')\" style=\"display:inline-block;background:rgba(193,53,132,.15);border:1px solid rgba(193,53,132,.3);color:#E1306C;border-radius:12px;padding:2px 8px;font-size:11px;margin:2px;cursor:pointer\" title=\"Click to copy\">$1</span>'');\n  // Parse QUEST block into button\n  html = html.replace(/\u26a1 QUEST: (.+?)\\nXP: (\\d+)\\nDEADLINE: (.+?)(?=\\n|$)/gs, (m, name, xp, deadline) =>\n    `<div style=\"background:rgba(225,48,108,.1);border:1px solid rgba(225,48,108,.3);border-radius:8px;padding:12px;margin-top:10px\">", "call_site_count": 2}]'::jsonb, 'unverified');
