INSERT INTO perspective_reports (scope_level, scope_id, scope_label, self_report, expected_behavior, evidence, status) VALUES ('mainjs_function', 'renderMarkdown', 'renderMarkdown', 'I am a real function defined at main.js legacy block:897, called 10 time(s) elsewhere in rpgace_core.js by a bare same-name call (a real, checkable but NOT exhaustive signal — see this generator''s own honest scope-limit note on hooks/DOM-event/callback-reference calls it cannot see).', 'Real behavior not yet hand-verified against live app use; my role is inferred from my own definition and detected call sites, not confirmed by direct observation.', '[{"cite": "main.js legacy block:897\nfunction renderMarkdown(text){\n  return _escChatHtml(text)\n    .replace(/^### (.+)$/gm,''<strong style=\"color:var(--gold2);font-size:13px\">$1</strong>'')\n    .replace(/^## (.+)$/gm,''<strong style=\"color:var(--gold);font-size:14px;display:block;margin-top:10px\">$1</strong>'')\n    .replace(/^# (.+)$/gm,''<strong style=\"color:var(--gold);font-size:15px;display:block;margin-top:10px\">$1</strong>'')\n    .replace(/\\*\\*(.+?)\\*\\*/g,''<strong>$1</strong>'')\n    .replace(/\\*(.+?)\\*/g,''<em>$1</em>'')\n    .replace(/`(.+?)`/g,''<code style=\"background:rgba(255,255,255,.08);padding:1px 5px;border-radius:3px;font-size:12px\">$1</code>'')", "call_site_count": 10}]'::jsonb, 'unverified');
