INSERT INTO perspective_reports (scope_level, scope_id, scope_label, self_report, expected_behavior, evidence, status) VALUES ('mainjs_function', 'renderVSTFooter', 'renderVSTFooter', 'I am a real function defined at main.js legacy block:2970, called 2 time(s) elsewhere in rpgace_core.js by a bare same-name call (a real, checkable but NOT exhaustive signal — see this generator''s own honest scope-limit note on hooks/DOM-event/callback-reference calls it cannot see).', 'Real behavior not yet hand-verified against live app use; my role is inferred from my own definition and detected call sites, not confirmed by direct observation.', '[{"cite": "main.js legacy block:2970\nfunction renderVSTFooter(vsts,rawContent){\n  if(!vsts || !vsts.length) return '''';\n  return `<div style=\"margin-top:16px;padding-top:12px;border-top:1px solid var(--border)\">\n    <div style=\"font-size:10px;color:#FF8C00;font-family:''Cinzel'',serif;letter-spacing:1px;margin-bottom:8px\">\ud83d\udd0c VSTs & EQUIPMENT DETECTED</div>\n    <div style=\"display:flex;flex-wrap:wrap;gap:5px\">\n      ${vsts.map(v => {\n        const anchor = ''vst-ref-'' + v.replace(/[^a-zA-Z0-9]/g,''-'').toLowerCase();\n        const ctx = extractVSTContext(rawContent, v);", "call_site_count": 2}]'::jsonb, 'unverified');
