INSERT INTO perspective_reports (scope_level, scope_id, scope_label, self_report, expected_behavior, evidence, status) VALUES ('mainjs_function', 'saveEncWithVSTs', 'saveEncWithVSTs', 'I am a real function defined at main.js legacy block:2986, called 2 time(s) elsewhere in rpgace_core.js by a bare same-name call (a real, checkable but NOT exhaustive signal — see this generator''s own honest scope-limit note on hooks/DOM-event/callback-reference calls it cannot see).', 'Real behavior not yet hand-verified against live app use; my role is inferred from my own definition and detected call sites, not confirmed by direct observation.', '[{"cite": "main.js legacy block:2986\nasync function saveEncWithVSTs(entry){\n  const vsts = extractVSTsFromText(entry.content || '''');\n  if(!vsts.length) return;\n  try {\n    await RPGACE.sb.secureWrite(''encyclopedia'', ''update'', { vst_tags: vsts }, ''id=eq.'' + entry.id);\n  } catch(e){}\n}\n", "call_site_count": 2}]'::jsonb, 'unverified');
INSERT INTO perspective_reports (scope_level, scope_id, scope_label, self_report, expected_behavior, evidence, status) VALUES ('mainjs_function', 'saveIntelToEncyclopedia', 'saveIntelToEncyclopedia', 'I am a real function defined at main.js legacy block:4508, called 2 time(s) elsewhere in rpgace_core.js by a bare same-name call (a real, checkable but NOT exhaustive signal — see this generator''s own honest scope-limit note on hooks/DOM-event/callback-reference calls it cannot see).', 'Real behavior not yet hand-verified against live app use; my role is inferred from my own definition and detected call sites, not confirmed by direct observation.', '[{"cite": "main.js legacy block:4508\nfunction saveIntelToEncyclopedia(index){\n  const insights=JSON.parse(localStorage.getItem(''rpgace_intel_insights'')||''[]'');\n  const item=insights[index]; if(!item) return;\n  const enc=item.insights?.encyclopedia_entry||{};\n  const content=`## ${enc.title||item.title}\\n\\n**Source:** ${item.title} by ${item.creator} (${item.platform})\\n**Score:** ${item.score}/10\\n**Date:** ${new Date(item.date||item.created_at).toLocaleDateString()}\\n\\n### Summary\\n${enc.summary||''''}\\n\\n### Key Learnings\\n${enc.key_learnings?.map(l=>''- ''+l).join(''\\n'')||''''}\\n\\n### Production Techniques\\n${(item.insights?.production_techniques||[]).map(t=>''- ''+t).join(''\\n'')}\\n\\n### What To Apply\\n${(item.insights?.what_to_steal||[]).map(s=>''\u2192 ''+s).join(''\\n'')}\\n\\n### Tags\\n${enc.tags?.join('', '')||''''}`;\n  // Aug 27 2026 (/Routine item #1) \u2014 pass the real source url through so\n  // this entry can enter the reanalysis pool if later deleted.\n  saveOracleToEncyclopedia(enc.title||item.title, content, item.url);", "call_site_count": 2}]'::jsonb, 'unverified');
INSERT INTO perspective_reports (scope_level, scope_id, scope_label, self_report, expected_behavior, evidence, status) VALUES ('mainjs_function', 'saveManualInsight', 'saveManualInsight', 'I am a real function defined at main.js legacy block:2703, called 1 time(s) elsewhere in rpgace_core.js by a bare same-name call (a real, checkable but NOT exhaustive signal — see this generator''s own honest scope-limit note on hooks/DOM-event/callback-reference calls it cannot see).', 'Real behavior not yet hand-verified against live app use; my role is inferred from my own definition and detected call sites, not confirmed by direct observation.', '[{"cite": "main.js legacy block:2703\nasync function saveManualInsight(){\n  removeInsightTooltip();\n  if(!_manualCtx) return;\n  const{entryId,entryTitle,text}=_manualCtx;\n  let micro=[],macro=detectCategory(text,'''');\n  try{\n    const data=await callOracle([{role:''user'',content:`2-3 micro-category tags and macro-category for this music producer insight:\\n\"${text}\"\\nJSON only: {\"micro_categories\":[\"Tag1\",\"Tag2\"],\"macro_category\":\"beat|mixing|vst|genre|artist|strategy|content|notes\"}`}],'''',120);\n    const raw=data.content.map(c=>c.text||'''').join('''').replace(/```json|```/g,'''').trim();", "call_site_count": 1}]'::jsonb, 'unverified');
