INSERT INTO perspective_reports (scope_level, scope_id, scope_label, self_report, expected_behavior, evidence, status) VALUES ('mainjs_function', 'showSuggestionPopup', 'showSuggestionPopup', 'I am a real function defined at main.js legacy block:929, called 2 time(s) elsewhere in rpgace_core.js by a bare same-name call (a real, checkable but NOT exhaustive signal — see this generator''s own honest scope-limit note on hooks/DOM-event/callback-reference calls it cannot see).', 'Real behavior not yet hand-verified against live app use; my role is inferred from my own definition and detected call sites, not confirmed by direct observation.', '[{"cite": "main.js legacy block:929\nfunction showSuggestionPopup(lines){const c=document.getElementById(''popup-tasks'');c.innerHTML='''';document.getElementById(''popup-msg'').textContent=''The Oracle has ''+lines.length+'' new quest''+(lines.length!==1?''s'':'''')+'' for you!'';lines.slice(0,3).forEach(line=>{const xm=line.match(/XP:\\s*(\\d+)/),nm=line.match(/QUEST:\\s*([^|]+)/);if(nm){const d=document.createElement(''div'');d.className=''popup-task'';d.innerHTML=`<span>\u2694 ${nm[1].trim()}</span><span class=\"popup-task-xp\">+${xm?xm[1]:50} XP</span>`;c.appendChild(d);}});document.getElementById(''suggestion-popup'').classList.add(''show'');}", "call_site_count": 2}]'::jsonb, 'unverified');
